123:/// Build the trusted decision envelope from server-resolved inputs. Candidate
124:/// strings, identity, policy, outcome and execution evidence are never trusted
125:/// from `RecordDecisionInput`.
126:pub fn build_shadow_record(
127:    decision_id: String,
128:    proposal: RecordDecisionInput,
129:    caller: VerifiedCaller,
130:    operation: ResolvedOperationRef,
131:    gate_input: GateInput,
132:    openflow_binding: Option<super::schema_tag_registry_methods::OpenFlowBindingRef>,
133:) -> Result<DecisionRecord> {
134:    proposal.validate()?;
135:    caller.validate()?;
136:    operation.validate()?;
137:    ensure!(
138:        proposal.candidate.plugin_id == operation.plugin_id,
139:        "candidate plugin does not match resolved operation"
140:    );
141:    ensure!(
142:        proposal.candidate.method_key == operation.method_key,
143:        "candidate method does not match resolved operation"
144:    );
145:    ensure!(
146:        proposal.candidate.schema_hash == operation.schema_hash,
147:        "candidate schema hash is stale"
148:    );
149:    ensure!(
150:        gate_input.caller == caller && gate_input.operation == operation,
151:        "gate context does not match trusted record context"
152:    );
153:    ensure!(
154:        gate_input.classification == proposal.classification_proposal,
155:        "gate classification does not match recorded proposal"
156:    );
157:    if let Some(binding) = &openflow_binding {
158:        binding.validate()?;
159:        ensure!(
160:            operation.plugin_id == binding.plugin_id
161:                && operation.method_key == binding.method_key
162:                && operation.schema_hash == binding.schema_hash,
163:            "OpenFlow binding does not match resolved operation"
164:        );
165:        if let Some(tag_id) = gate_input.resolved_tag.as_ref().map(|tag| tag.tag_id) {
166:            ensure!(
167:                tag_id == binding.network_tag_id,
168:                "OpenFlow binding does not match resolved network tag"
169:            );
170:        }
171:    }
172:    let mut gate_result = evaluate_gate(&gate_input);
173:    let mut canonical_mappings: Vec<super::schema_tag_registry_methods::CanonicalMappingRef> =
174:        if gate_result.outcome == GateOutcome::Denied {
